sys_ui_action.script:
function complianceCheck() {

    g_form.clearMessages();
    g_form.addSuggestionMessage("Generating Quality Check via Now Assist... please wait.");

    var ga = new GlideAjax('sn_itsm_gen_ai.synergizeDemoUtils');
    ga.addParam('sysparm_name', 'getQualityCompliance');
    ga.addParam('sysparm_inc_id', g_form.getUniqueValue());

    ga.getXMLAnswer(function(response) {

        g_form.clearMessages();

        if (!response) {
            g_form.addErrorMessage("No response received from the server.");
            return;
        }

        var finalPlainOutput = cleanQualityCheckOutput(response);

        if (finalPlainOutput.indexOf("ERROR:") === 0) {
            g_form.addErrorMessage(finalPlainOutput.replace("ERROR:", "").trim());
            return;
        }

        /*
         Optional:
         Store plain text output in a field if needed.
         Replace u_quality_check_output with your actual field name.
        */
        if (g_form.getControl('u_quality_check_output')) {
            g_form.setValue('u_quality_check_output', finalPlainOutput);
        }

        /*
         Display formatted output in the ServiceNow suggestion message banner.
        */
        var finalHtmlOutput = convertQualityCheckToHtml(finalPlainOutput);
        //g_form.addSuggestionMessage(finalHtmlOutput);

        showIncidentQualityDialog(finalHtmlOutput);



        //get Dialouge box

        function showIncidentQualityDialog(finalHtmlOutput) {
            try {
                var pageDocument =
                    document;

                if (
                    typeof top !== 'undefined' &&
                    top.document &&
                    top.document.body
                ) {
                    pageDocument =
                        top.document;
                }

                var existingOverlay =
                    pageDocument.getElementById(
                        'incident_quality_overlay'
                    );

                if (existingOverlay) {
                    existingOverlay.parentNode.removeChild(
                        existingOverlay
                    );
                }

                var qualityOutput =
                    finalHtmlOutput ||
                    '<p>No quality recommendations are available.</p>';

                var overlay =
                    pageDocument.createElement('div');

                overlay.id =
                    'incident_quality_overlay';

                overlay.style.position =
                    'fixed';

                overlay.style.top =
                    '0';

                overlay.style.left =
                    '0';

                overlay.style.right =
                    '0';

                overlay.style.bottom =
                    '0';

                overlay.style.width =
                    '100%';

                overlay.style.height =
                    '100%';

                overlay.style.background =
                    'rgba(15, 23, 42, 0.58)';

                overlay.style.zIndex =
                    '2147483647';

                overlay.style.display =
                    'flex';

                overlay.style.alignItems =
                    'center';

                overlay.style.justifyContent =
                    'center';

                overlay.style.padding =
                    '24px';

                overlay.style.boxSizing =
                    'border-box';

                var dialog =
                    pageDocument.createElement('div');

                dialog.id =
                    'incident_quality_dialog';

                dialog.style.width =
                    '90%';

                dialog.style.maxWidth =
                    '1100px';

                dialog.style.maxHeight =
                    '88vh';

                dialog.style.background =
                    'linear-gradient(' +
                    '120deg,' +
                    '#d2ffd5 0%,' +
                    '#c7f9df 48%,' +
                    '#c4edff 100%' +
                    ')';

                dialog.style.border =
                    '1px solid #91dca8';

                dialog.style.borderRadius =
                    '12px';

                dialog.style.boxShadow =
                    '0 24px 70px rgba(15, 23, 42, 0.38)';

                dialog.style.overflow =
                    'hidden';

                dialog.style.display =
                    'flex';

                dialog.style.flexDirection =
                    'column';

                dialog.style.fontFamily =
                    'Arial, Helvetica, sans-serif';

                dialog.style.boxSizing =
                    'border-box';

                var header =
                    pageDocument.createElement('div');

                header.style.display =
                    'flex';

                header.style.alignItems =
                    'center';

                header.style.justifyContent =
                    'space-between';

                header.style.padding =
                    '20px 28px';

                header.style.background =
                    'linear-gradient(' +
                    '110deg,' +
                    '#c6ffc9 0%,' +
                    '#c0f8dc 50%,' +
                    '#bcecff 100%' +
                    ')';

                header.style.borderBottom =
                    '1px solid #91dca8';

                header.style.flexShrink =
                    '0';

                var heading =
                    pageDocument.createElement('div');

                heading.innerHTML =
                    '&#10024; Incident Quality Checker';

                heading.style.fontSize =
                    '22px';

                heading.style.fontWeight =
                    '700';

                heading.style.color =
                    '#142f24';

                var closeButton =
                    pageDocument.createElement('button');

                closeButton.type =
                    'button';

                closeButton.id =
                    'incident_quality_close';

                closeButton.innerHTML =
                    '&#10005;';

                closeButton.setAttribute(
                    'aria-label',
                    'Close'
                );

                closeButton.style.border =
                    '0';

                closeButton.style.background =
                    'transparent';

                closeButton.style.color =
                    '#1e3a4a';

                closeButton.style.fontSize =
                    '23px';

                closeButton.style.lineHeight =
                    '1';

                closeButton.style.padding =
                    '6px 9px';

                closeButton.style.cursor =
                    'pointer';

                closeButton.style.borderRadius =
                    '7px';

                header.appendChild(
                    heading
                );

                header.appendChild(
                    closeButton
                );

                var body =
                    pageDocument.createElement('div');

                body.style.padding =
                    '22px 28px 12px 28px';

                body.style.display =
                    'flex';

                body.style.flexDirection =
                    'column';

                body.style.flex =
                    '1';

                body.style.minHeight =
                    '0';

                body.style.boxSizing =
                    'border-box';

                var content =
                    pageDocument.createElement('div');

                content.id =
                    'incident_quality_content';

                content.innerHTML =
                    qualityOutput;

                content.style.background =
                    'rgba(255, 255, 255, 0.67)';

                content.style.border =
                    '1px solid #86d29e';

                content.style.borderRadius =
                    '9px';

                content.style.padding =
                    '23px 27px';

                content.style.height =
                    '430px';

                content.style.maxHeight =
                    '58vh';

                content.style.overflowY =
                    'auto';

                content.style.color =
                    '#17212b';

                content.style.fontSize =
                    '15px';

                content.style.lineHeight =
                    '1.7';

                content.style.boxSizing =
                    'border-box';

                body.appendChild(
                    content
                );

                var actions =
                    pageDocument.createElement('div');

                actions.style.display =
                    'flex';

                actions.style.justifyContent =
                    'flex-end';

                actions.style.alignItems =
                    'center';

                actions.style.gap =
                    '16px';

                actions.style.padding =
                    '16px 28px 24px 28px';

                actions.style.flexShrink =
                    '0';

                var skipButton =
                    pageDocument.createElement('button');

                skipButton.type =
                    'button';

                skipButton.id =
                    'incident_quality_skip';

                skipButton.textContent =
                    'Skip Suggestions';

                skipButton.style.minWidth =
                    '175px';

                skipButton.style.padding =
                    '12px 21px';

                skipButton.style.border =
                    '1px solid #155eef';

                skipButton.style.borderRadius =
                    '9px';

                skipButton.style.background =
                    '#ffffff';

                skipButton.style.color =
                    '#1355d5';

                skipButton.style.fontSize =
                    '14px';

                skipButton.style.fontWeight =
                    '700';

                skipButton.style.cursor =
                    'pointer';

                var acceptButton =
                    pageDocument.createElement('button');

                acceptButton.type =
                    'button';

                acceptButton.id =
                    'incident_quality_accept';

                acceptButton.textContent =
                    'Accept Suggestions';

                acceptButton.style.minWidth =
                    '190px';

                acceptButton.style.padding =
                    '12px 21px';

                acceptButton.style.border =
                    '1px solid #118447';

                acceptButton.style.borderRadius =
                    '9px';

                acceptButton.style.background =
                    'linear-gradient(' +
                    '110deg,' +
                    '#19a556 0%,' +
                    '#138d5c 100%' +
                    ')';

                acceptButton.style.color =
                    '#ffffff';

                acceptButton.style.fontSize =
                    '14px';

                acceptButton.style.fontWeight =
                    '700';

                acceptButton.style.cursor =
                    'pointer';

                acceptButton.style.boxShadow =
                    '0 6px 16px rgba(16, 130, 70, 0.25)';

                actions.appendChild(
                    skipButton
                );

                actions.appendChild(
                    acceptButton
                );

                dialog.appendChild(
                    header
                );

                dialog.appendChild(
                    body
                );

                dialog.appendChild(
                    actions
                );

                overlay.appendChild(
                    dialog
                );

                pageDocument.body.appendChild(
                    overlay
                );

                function closeQualityDialog() {
                    var currentOverlay =
                        pageDocument.getElementById(
                            'incident_quality_overlay'
                        );

                    if (
                        currentOverlay &&
                        currentOverlay.parentNode
                    ) {
                        currentOverlay.parentNode.removeChild(
                            currentOverlay
                        );
                    }
                }

                acceptButton.onclick =
                    function(event) {
                        if (event) {
                            event.preventDefault();
                            event.stopPropagation();
                        }

                        //alert('Accept clicked');

                        var updateWorkNotes = new GlideAjax('sn_itsm_gen_ai.synergizeDemoUtils');
                        updateWorkNotes.addParam('sysparm_name', 'addQualitySuggestionsToWorkNotes');
                        updateWorkNotes.addParam('sysparm_incid', g_form.getUniqueValue());
                        updateWorkNotes.addParam('sysparm_nowassistsuggestion', finalHtmlOutput);
                        updateWorkNotes.getXMLAnswer(updateNotes);

                        function updateNotes(response) {
                            closeQualityDialog();
                            g_form.clearMessages();
                            g_form.addSuggestionMessage(response);
                        }

                        return false;
                    };

                skipButton.onclick =
                    function(event) {
                        if (event) {
                            event.preventDefault();
                            event.stopPropagation();
                        }
                        closeQualityDialog();

                        // 1. Show the redirecting message on the form
                        g_form.clearMessages();
                        g_form.addSuggestionMessage('Redirecting to the incident list view in 2 seconds...');
                        setTimeout(function() {
                            g_navigation.open('incident_list.do?sysparm_query=active=true^priority=1', '_self');
                        }, 2000);
                        return false;
                    };

                closeButton.onclick =
                    function(event) {
                        if (event) {
                            event.preventDefault();
                            event.stopPropagation();
                        }

                        closeQualityDialog();

                        return false;
                    };

                overlay.onclick =
                    function(event) {
                        if (
                            event &&
                            event.target === overlay
                        ) {
                            closeQualityDialog();
                        }
                    };

            } catch (ex) {
                console.error(
                    'Incident Quality Dialog error:',
                    ex
                );

                alert(
                    'Unable to open quality dialog: ' +
                    ex.message
                );
            }
        }






    });
}


function cleanQualityCheckOutput(response) {

    var output = response + '';

    /*
     1. Decode escaped characters.
    */
    output = output.replace(/\\r\\n/g, '\n');
    output = output.replace(/\\n/g, '\n');
    output = output.replace(/\\r/g, '\n');
    output = output.replace(/\\t/g, ' ');
    output = output.replace(/\\"/g, '"');

    /*
     2. Decode common HTML entities.
     Keeping &lt; and &gt; as encoded because this is working
     with addSuggestionMessage in your instance.
    */
    output = output.replace(/&lt;/g, '&lt;');
    output = output.replace(/&gt;/g, '&gt;');
    output = output.replace(/&amp;/g, '&');
    output = output.replace(/&quot;/g, '"');
    output = output.replace(/'/g, "'");

    /*
     3. Try JSON parse if the response is proper JSON.
    */
    try {
        var parsed = JSON.parse(output);

        if (parsed.error) {
            return "ERROR: " + parsed.error;
        }

        if (parsed.model_output) {
            output = parsed.model_output + '';
        } else if (parsed.output) {
            output = parsed.output + '';
        } else if (parsed.result) {
            output = parsed.result + '';
        }

    } catch (e) {
        /*
         Not valid JSON.
         Continue with string cleanup.
        */
    }

    output = output.trim();

    /*
     4. Remove model_output wrapper even if response is not valid JSON.
     Handles:
     "model_output": "&lt;br&gt;..."
     {"model_output": "&lt;br&gt;..."}
    */
    output = output.replace(/^\s*\{?\s*"model_output"\s*:\s*/i, '');
    output = output.replace(/^\s*\{?\s*model_output\s*:\s*/i, '');

    output = output.trim();

    /*
     5. Remove only outer starting quote.
    */
    if (output.charAt(0) === '"') {
        output = output.substring(1);
    }

    output = output.trim();

    /*
     6. Remove closing quote and brace at the end.
     This removes trailing:
     "}
     "}
     "
     }
    */
    output = output.replace(/"\s*\}\s*$/g, '');
    output = output.replace(/\}\s*$/g, '');
    output = output.replace(/"\s*$/g, '');

    output = output.trim();

    /*
     7. Remove markdown wrappers.
    */
    output = output.replace(/```markdown/gi, '');
    output = output.replace(/```/g, '');

    /*
     8. Convert HTML line breaks into actual new lines.
    */
    output = output.replace(/&lt;br\s*\/?&gt;/gi, '\n');

    /*
     9. Remove original strong tags and all HTML tags.
     This removes:
     &lt;strong data-lexical-text="true"&gt;
     &lt;/strong&gt;
    */
    output = output.replace(/&lt;strong[^&gt;]*&gt;/gi, '');
    output = output.replace(/&lt;\/strong&gt;/gi, '');
    output = output.replace(/&lt;[^&gt;]+&gt;/g, '');

    /*
     10. Remove markdown bold symbols.
    */
    output = output.replace(/\*\*/g, '');

    /*
     11. Remove remaining unnecessary backslashes.
    */
    output = output.replace(/\\/g, '');

    /*
     12. Remove model_output again in case it remained after tag cleaning.
    */
    output = output.replace(/^\s*\{?\s*"model_output"\s*:\s*/i, '');
    output = output.replace(/^\s*\{?\s*model_output\s*:\s*/i, '');

    output = output.trim();

    /*
     13. Remove remaining outer quotes/braces again.
    */
    if (output.charAt(0) === '"') {
        output = output.substring(1);
    }

    output = output.replace(/"\s*\}\s*$/g, '');
    output = output.replace(/\}\s*$/g, '');
    output = output.replace(/"\s*$/g, '');

    output = output.trim();

    /*
     14. Normalize Quality Check.
    */
    output = output.replace(/Quality Check:\s*(\d+)\s*%/i, 'Quality Check: $1%');

    /*
     15. Normalize Recommendations.
     Creates a blank line between Quality Check and Recommendations.
    */
    output = output.replace(/\s*Recommendations:\s*/i, '\n\nRecommendations:\n\n');

    /*
     16. Put each recommendation point on a new line.
     This avoids breaking values like Priority (5).
    */
    output = output.replace(/\s+([1-9]\d?\)\s+[A-Z])/g, '\n\n$1');

    /*
     17. Clean spacing.
    */
    output = output.replace(/[ \t]+/g, ' ');
    output = output.replace(/\n[ \t]+/g, '\n');
    output = output.replace(/\n{5,}/g, '\n\n');

    /*
     18. Ensure final desired spacing:
     Quality Check: 35%

     Recommendations:

     1) ...
    */
    output = output.replace(/(Quality Check:\s*\d+%)\s*\n+\s*(Recommendations:)/i, '$1\n\n$2');
    output = output.replace(/(Recommendations:)\s*\n+(\d+\))/i, '$1\n\n$2');

    /*
     19. Final cleanup for any leftover closing characters.
    */
    output = output.replace(/"\s*\}\s*$/g, '');
    output = output.replace(/\}\s*$/g, '');
    output = output.replace(/"\s*$/g, '');

    return output.trim();
}


function convertQualityCheckToHtml(plainText) {

    var html = plainText || '';

    /*
     1. Extract quality score.
    */
    var score = 0;
    var scoreMatch = html.match(/Quality Check:\s*(\d+)%/i);

    if (scoreMatch && scoreMatch.length > 1) {
        score = parseInt(scoreMatch[1], 10);
    }

    //Scoreupdate

    var ga = new GlideAjax('sn_itsm_gen_ai.synergizeDemoUtils');
    ga.addParam('sysparm_name', 'updateAuditScore');
    ga.addParam('sysparm_incVal', g_form.getUniqueValue());
    ga.addParam('sysparm_auditScore', score);
    ga.getXMLAnswer(updateAuditRec);

    function updateAuditRec(response) {
        g_form.clearMessages();
        if (g_form.getValue('u_audit_score') != score) {
            g_form.addSuggestionMessage('Audit Score recalculated by Now Assist');
        } else {
            g_form.addInfoMessage('Audit Score has no change. Please Follow the recommendations by Now Assist to improve score');
        }

    }

    //Scoreupdate

    /*
     2. Continuous 3-color logic.
     Every percentage from 0 to 100 is covered.

     0  to 30  = Red
     31 to 70  = Blue
     71 to 100 = Dark Green
    */
    var scoreColor = '#000000';

    if (score >= 0 && score <= 30) {
        scoreColor = '#D71920'; // Red
    } else if (score >= 31 && score <= 70) {
        scoreColor = '#0070C0'; // Blue
    } else if (score >= 71 && score <= 100) {
        scoreColor = '#006100'; // Dark Green
    }

    /*
     3. Use actual HTML tags here.
     Do not use &lt;b&gt; or &lt;br/&gt; here.
     addSuggestionMessage is rendering actual <b> correctly in your instance.
    */

    /*
     4. Bold Quality Check and color-code percentage.
    */
    html = html.replace(
        /Quality Check:\s*(\d+)%/i,
        '<b>Quality Check:</b> <font color="' + scoreColor + '"><b>$1%</b></font>'
    );

    /*
     5. Bold Recommendations heading.
    */
    html = html.replace(
        /Recommendations:/i,
        '<b>Recommendations:</b>'
    );

    /*
     6. Bold only recommendation title before colon.
     Example:
     1) Short Description Formatting:
     becomes:
     1) <b>Short Description Formatting:</b>

     The explanation after the colon remains normal.
    */
    html = html.replace(
        /(^|\n+)([1-9]\d?\)\s+)([^:\n]{2,180}:)/g,
        function(match, lineBreaks, numberPart, titlePart) {
            return lineBreaks +
                numberPart +
                '<b>' +
                titlePart +
                '</b>';
        }
    );

    /*
     7. Convert line breaks to visible HTML breaks.
     Use actual <br/> tags.
    */
    html = html.replace(/\n/g, '<br/>');

    return html;



    //dialouge box


}
